<script>
  import { localStore } from '@splendidlabz/utils/dom'
  import { onMount } from 'svelte'

  const { name } = $props()

  onMount(store)

  function store() {
    if (typeof window === 'undefined') return
    if (!name) throw new Error('name is required')
    localStore.remove(name)
  }
</script>
